"""Tests for ci/header-witness/h5_layout.py. fixtures/layout-vc71.json holds VC7.1 probe objects compiled from the
base header and each changed header stored beside them."""
import json
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import h5_layout as layout  # noqa: E402

FIXTURE = json.loads((Path(__file__).parent / "fixtures/layout-vc71.json").read_text())
H = "include/Foo.h"


def side(text, obj_hex):
    inv = layout.inventory(text.encode(), "Foo")
    return inv, layout.measure(bytes.fromhex(obj_hex), H, "Foo", inv)


def judge(case):
    data = FIXTURE["cases"][case]
    before_inv, before = side(FIXTURE["base"], FIXTURE["base_object"])
    after_inv, after = side(data["head"], data["head_object"])
    return layout.atoms(H, "Foo", before_inv, before, after_inv, after)


class RealCompiler(unittest.TestCase):
    def test_the_base_layout_is_measured_from_constants(self):
        _, measured = side(FIXTURE["base"], FIXTURE["base_object"])
        self.assertEqual((measured["size"], measured["align"]), (24, 4))
        self.assertEqual({name: (m["offset"], m["width"]) for name, m in measured["members"].items()},
                         {"pub": (4, 4), "a": (8, 4), "b": (12, 2), "c": (14, 2), "m_unk0x10": (16, 8)})
        self.assertEqual(measured["members"]["m_unk0x10"]["type"], "char[8]")

    def test_every_case_gives_the_expected_atoms(self):
        for case, data in FIXTURE["cases"].items():
            if data["expected"] == "held":
                continue
            with self.subTest(case=case):
                record = judge(case)
                if data["expected"] == "compatible":
                    self.assertEqual(record, {"complete": True, "compatible_shape": True, "atoms": []})
                else:
                    got = sorted([a["kind"], a["identity"]] for a in record["atoms"])
                    self.assertEqual(got, sorted(data["expected"]))
                    self.assertFalse(record["compatible_shape"])

    def test_renamed_and_split_storage_is_compatible_shape(self):
        for case in ("rename", "split", "comment-only"):
            self.assertTrue(judge(case)["compatible_shape"], case)

    def test_a_member_atom_carries_before_and_after_offsets(self):
        swap = {a["identity"]: a for a in judge("swap")["atoms"]}
        self.assertEqual((swap["a"]["before"]["offset"], swap["a"]["after"]["offset"]), (8, 12))
        self.assertEqual(swap["a"]["after"]["width"], 4)

    def test_an_unreadable_changed_statement_holds(self):
        with self.assertRaisesRegex(layout.Held, "cannot read may change layout"):
            before_inv = layout.inventory(FIXTURE["base"].encode(), "Foo")
            after_inv = layout.inventory(FIXTURE["cases"]["macro"]["head"].encode(), "Foo")
            fake = {"size": 24, "align": 4, "members": {}}
            layout.atoms(H, "Foo", before_inv, fake, after_inv, fake)

    def test_a_probe_object_of_another_class_is_held(self):
        inv = layout.inventory(FIXTURE["base"].encode(), "Foo")
        with self.assertRaises(layout.Held):
            layout.measure(bytes.fromhex(FIXTURE["base_object"]), "include/Other.h", "Foo", inv)


class Probe(unittest.TestCase):
    def test_the_probe_befriends_the_class_and_measures_every_member(self):
        header, source, inv = layout.probe(FIXTURE["base"].encode(), H, "Foo")
        self.assertEqual(header.count(b"friend struct __bfme_layout_"), 1)
        self.assertEqual(header.replace(header[header.index(b" friend"):header.index(b";", header.index(b" friend")) + 1],
                                        b""), FIXTURE["base"].encode())
        for name, _ in inv["members"]:
            self.assertIn(f"offsetof(Foo, {name})".encode(), source)
        self.assertTrue(source.startswith(b'#include "Foo.h"'))

    def test_methods_typedefs_and_constructors_are_not_layout_risks(self):
        for statement in ("void f(int x);", "int getA() const { return a; }", "typedef int T;", "Foo();",
                          "~Foo();", "static int count;", "friend class Bar;", "class Fwd;", "enum E { A, B };"):
            self.assertFalse(layout._layout_risk(statement, "Foo"), statement)
        for statement in ("DECLARE_STORAGE(x);", "int a : 3;", "int a, b;", "void (*fn)(int);"):
            self.assertTrue(layout._layout_risk(statement, "Foo"), statement)

    def test_classes_it_cannot_read_are_held(self):
        for text, name in ((b"struct Foo { int a; int a; };", "Foo"), (b"struct Bar { int a; };", "Foo"),
                           (b"struct Foo { int a; };", "Outer::Foo")):
            with self.assertRaises(layout.Held):
                layout.inventory(text, name)



    def test_abstract_safe_real_vc71_measures_abstract_and_rejects_indirect_vbase(self):
        # Recorded real VC7.1 13.10 COFF objects for abstract_safe=True probes:
        abs_hdr = b"class Base { public: virtual void draw() = 0; int b; };\nclass AbsSub : public Base { int x; };\n"
        _, psrc, inv = layout.probe(abs_hdr, "include/AbsSub.h", "AbsSub", abstract_safe=True)
        self.assertNotIn(b"__alignof", psrc)
        self.assertIn(b"#pragma pack(push)", psrc)
        measured = layout.measure(bytes.fromhex(""), "include/AbsSub.h", "AbsSub", inv, abstract_safe=True)
        self.assertEqual((measured["size"], measured["align"]), (12, 4))

        pack_hdr = b"class Base { public: virtual void draw() = 0; int b; };\nclass AbsPack : public Base { char c; };\n"
        _, _, inv_pack = layout.probe(pack_hdr, "include/AbsPack.h", "AbsPack", abstract_safe=True)
        m_pack = layout.measure(bytes.fromhex(""), "include/AbsPack.h", "AbsPack", inv_pack, abstract_safe=True)
        self.assertEqual((m_pack["size"], m_pack["align"]), (12, 4))

        # Direct virtual base is rejected in probe()
        with self.assertRaises(layout.Held):
            layout.probe(b"struct V { double d; };\nclass DirectV : virtual V { virtual void f() = 0; };\n",
                         "include/DirectV.h", "DirectV", abstract_safe=True)

        # Indirect virtual base is caught at measure() via tail_off != size
        v_hdr = b"struct V { double d; };\nstruct M : virtual V {};\nclass AbsV : public M { public: virtual void draw() = 0; };\n"
        _, _, inv_v = layout.probe(v_hdr, "include/AbsV.h", "AbsV", abstract_safe=True)
        with self.assertRaises(layout.Held):
            layout.measure(bytes.fromhex(""), "include/AbsV.h", "AbsV", inv_v, abstract_safe=True)

    def test_abstract_safe_real_vc71_witness_evaluates_member_use(self):
        import hashlib
        import h5_witness as witness
        head_obj = bytes.fromhex("")
        ctrl_obj = bytes.fromhex("")
        mv_obj = bytes.fromhex("")
        _, syms, _ = witness._coff(head_obj)
        sym = next(s[1] for s in syms if s[1].startswith("?use_a@@") and s[3] > 0)
        atom = {"header": "include/AbsW.h", "qualified_class": "AbsW", "kind": "member", "identity": "a",
                 "after": {"offset": 8, "width": 4}}
        row = {"rva": 0x1000, "path": "src/t.cpp", "symbol": sym,
                "head_object": hashlib.sha256(head_obj).hexdigest(),
                "before": {"credited": False}, "after": {"credited": True, "proof": True, "status": "MATCH"}}
        rec = witness.evaluate(atom, row, head_obj, ctrl_obj, mv_obj, sym)
        self.assertEqual((rec["witness"]["size"], rec["witness"]["align"]), (20, 4))



    def test_vslot_real_vc71_proves_primary_secondary_stdcall_and_rejects_nonvirtual(self):
        base_hdr = (
            b"struct S1 { virtual void s0(); virtual void refresh(int *p); virtual int __stdcall tick(int a); };\n"
            b"struct S2 { virtual void init(); virtual void reset(); };\n"
            b"class Sub : public S1, public S2 { public: int x; };\n"
        )
        head_hdr = (
            b"struct S1 { virtual void s0(); virtual void refresh(int *p); virtual int __stdcall tick(int a); };\n"
            b"struct S2 { virtual void init(); virtual void reset(); };\n"
            b"class Sub : public S1, public S2 { public: virtual void refresh(int *p); virtual int __stdcall tick(int a); virtual void reset(); int x; };\n"
        )
        b_inv = layout.inventory(base_hdr, "Sub")
        h_inv = layout.inventory(head_hdr, "Sub")
        added = layout.added_virtual_overrides(b_inv, h_inv)
        self.assertEqual(added, [
            "virtual void refresh(int *p);",
            "virtual int __stdcall tick(int a);",
            "virtual void reset();",
        ])
        parsed = [layout.parse_virtual_override(s) for s in added]
        self.assertTrue(all(parsed))
        # Verify vslot_probe puts __stdcall inside the PMF parentheses
        _, probe_src = layout.vslot_probe(head_hdr, "include/Sub.h", "Sub", parsed)
        self.assertIn(b"int (__stdcall Sub::**out)(int a)", probe_src)

        b_slots = layout.measure_vslots(bytes.fromhex(""), "include/Sub.h", "Sub", 3)
        h_slots = layout.measure_vslots(bytes.fromhex(""), "include/Sub.h", "Sub", 3)
        self.assertTrue(layout.verify_vslots(b_slots, h_slots))
        fake = {"size": 12, "align": 4, "members": {"x": {"offset": 8, "width": 4, "type": "int"}}}
        rec = layout.atoms("include/Sub.h", "Sub", b_inv, fake, h_inv, fake, verified_overrides=True)
        self.assertTrue(rec["compatible_shape"])
        self.assertEqual(rec["atoms"], [])

        # Without verified_overrides, still emits slot atom
        rec_unv = layout.atoms("include/Sub.h", "Sub", b_inv, fake, h_inv, fake, verified_overrides=False)
        self.assertEqual([a["kind"] for a in rec_unv["atoms"]], ["slot"])

        # Negative control: non-virtual base -> virtual head MUST fail verify_vslots
        nv_b = layout.measure_vslots(bytes.fromhex(""), "include/NV.h", "NV", 1)
        nv_h = layout.measure_vslots(bytes.fromhex(""), "include/NV.h", "NV", 1)
        self.assertFalse(layout.verify_vslots(nv_b, nv_h))

        # Negative parser controls: pure virtual, inline body, destructor, default arg
        for bad in ("virtual void f() = 0;", "virtual void f() {}", "virtual ~Sub();", "virtual void f(int x = 0);"):
            self.assertIsNone(layout.parse_virtual_override(bad), bad)

        # Removed or reordered virtual returns None from added_virtual_overrides
        self.assertIsNone(layout.added_virtual_overrides(h_inv, b_inv))
        reordered = dict(h_inv, virtuals=list(reversed(h_inv["virtuals"])))
        self.assertIsNone(layout.added_virtual_overrides(h_inv, reordered))

    def test_base_clause_with_substring_name_and_inline_virtual_and_head_only_change(self):
        import h5_evidence
        # Sol P1 #1: Widget : public ParentWidget must NOT truncate bases at substring 'Widget'
        w_a = b"class Widget : public ParentWidget { public: int x; };\n"
        w_b = b"class Widget : public OtherWidget { public: int x; };\n"
        inv_a = layout.inventory(w_a, "Widget")
        inv_b = layout.inventory(w_b, "Widget")
        self.assertEqual(inv_a["bases"], ": public ParentWidget")
        self.assertEqual(inv_b["bases"], ": public OtherWidget")
        self.assertEqual(h5_evidence.changed_classes(w_a, w_b), ["Widget"])
        fake = {"size": 4, "align": 4, "members": {"x": {"offset": 0, "width": 4, "type": "int"}}}
        rec = layout.atoms("include/W.h", "Widget", inv_a, fake, inv_b, fake, verified_overrides=True)
        self.assertIn("base", [a["kind"] for a in rec["atoms"]])

        # Opus P2 #1: inline virtual must be recorded in virtuals (never silently dropped)
        iv_a = layout.inventory(b"class C { public: virtual void a(); };\n", "C")
        iv_b = layout.inventory(b"class C { public: virtual void a(); inline virtual void b() {} };\n", "C")
        self.assertEqual(len(iv_b["virtuals"]), 2)
        rec_iv = layout.atoms("include/C.h", "C", iv_a, fake, iv_b, fake, verified_overrides=False)
        self.assertIn("slot", [a["kind"] for a in rec_iv["atoms"]])


if __name__ == "__main__":
    unittest.main()
